const v = $json;
return [{
  json: {
    destination: v.Destination,
    checkin: v['Check-in Date'],
    checkout: v['Check-out Date'],
    adults: Number(v.Adults || 1),
    children: Number(v.Children || 0),
    rooms: Number(v.Rooms || 1),
    nationality: String(v.Nationality || 'IN'),
    currency: String(v.Currency || 'USD'),
    hotelIndex: Math.max(0, Number(v['Hotel Index'] || 0)),
    roomIndex: Math.max(0, Number(v['Room Index'] || 0))
  }
}];

const form = $items('Normalize Input', 0, 0)[0].json;
const rawText = $json.response?.[0]?.text || '{}';
const parsed = JSON.parse(rawText);
const list = parsed.result || parsed.data || parsed.destinations || [];
const destination = Array.isArray(list) ? list[0] : null;
const destinationId = destination?.id || destination?.code || destination?.destinationId;

const today = new Date();
today.setDate(today.getDate() + 30)
const checkInDate = today.toISOString().split("T")[0];
today.setDate(today.getDate() + 1)
const checkOutDate = today.toISOString().split("T")[0];
if (!destinationId) {
  throw new Error('No destinationId found from hotel_search_destinations response');
}

return {
    "destinationId": destinationId,
    "checkIn": form.checkin || checkInDate,
    "checkOut": form.checkout || checkOutDate,
    "rooms": [{
      adults: form.adults
    }],
    "lat": destination.coordinates.lat,
    "long": destination.coordinates.long,
    "currency": form.currency
}

const ctx = $items('Prepare Hotel Search Args', 0, 0)[0].json;
const rawText = $json.response?.[0]?.text || '{}';
const parsed = JSON.parse(rawText);
const token = parsed?.result?.token;
const correlationId = parsed?.result?.correlationId;
const hotels = parsed?.result?.result || [];
if (!Array.isArray(hotels) || hotels.length === 0) {
  throw new Error('No hotels found');
}
const index = Math.min(ctx.hotelIndex || 0, hotels.length - 1);
const selectedHotel = hotels[index];
const hotelId = selectedHotel?.id || selectedHotel?.hotelId;
if (!hotelId) {
  throw new Error('No hotelId found in selected hotel');
}
return [{
  json: {
    ...ctx,
    token,
    correlationId,
    hotelId,
    hotelName: selectedHotel?.name || '',
    selectedHotel
  }
}];

const ctx = $items('Prepare Hotel Selection', 0, 0)[0].json;
const rawText = $json.response?.[0]?.text || '{}';
const parsed = JSON.parse(rawText);
const groups = parsed?.result?.groups || [];
const rooms = groups.flatMap(g => g.rooms || []);
if (!rooms.length) {
  throw new Error('No rooms found for selected hotel');
}
const index = Math.min(ctx.roomIndex || 0, rooms.length - 1);
const room = rooms[index];
const roomId = room?.id;
const recommendationId = room?.recommendationId;
const publishedRate = room?.publishedRate;
if (!roomId || !recommendationId) {
  throw new Error('Missing roomId/recommendationId for hotel_revalidate_rate');
}
return [{
  json: {
    ...ctx,
    roomId,
    recommendationId,
    publishedRate,
    selectedRoom: room
  }
}];

const hotelCtx = $items('Prepare Hotel Selection', 0, 0)[0].json;
const detailText = $items('Get Hotel Details', 0, 0)[0].json.response?.[0]?.text || '{}';
const revalidateText = $items('Revalidate', 0, 0)[0].json.response?.[0]?.text || '{}';
const paymentText = $json.response?.[0]?.text || '{}';
let details = {}; let revalidated = {}; let payment = {};
try { details = JSON.parse(detailText); } catch {}
try { revalidated = JSON.parse(revalidateText); } catch {}
try { payment = JSON.parse(paymentText); } catch {}
return [{
  json: {
    success: true,
    destination: hotelCtx.destination,
    hotel: {
      id: hotelCtx.hotelId,
      name: hotelCtx.hotelName,
      details
    },
    room: hotelCtx.selectedRoom,
    revalidated,
    payment
  }
}];
